create table public.buddy_research_facts (id uuid not null default gen_random_uuid(), mission_id uuid not null, source_id uuid not null, fact_type text not null, value jsonb not null, confidence numeric not null, extracted_by text not null, extraction_path text, extracted_at timestamp with time zone not null default now(), as_of_date date, CHECK (((confidence >= (0)::numeric) AND (confidence <= (1)::numeric))), CHECK ((extracted_by = ANY (ARRAY['rule'::text, 'model'::text]))), CHECK ((fact_type = ANY (ARRAY['market_size'::text, 'market_growth_rate'::text, 'employment_count'::text, 'employment_growth'::text, 'average_wage'::text, 'establishment_count'::text, 'competitor_name'::text, 'competitor_ticker'::text, 'competitor_revenue'::text, 'competitor_employees'::text, 'market_share_estimate'::text, 'population'::text, 'median_income'::text, 'business_density'::text, 'regulatory_body'::text, 'compliance_requirement'::text, 'recent_enforcement'::text, 'other'::text]))), PRIMARY KEY (id));
create table public.buddy_research_inferences (id uuid not null default gen_random_uuid(), mission_id uuid not null, inference_type text not null, conclusion text not null, input_fact_ids uuid[] not null, confidence numeric not null, reasoning text, created_at timestamp with time zone not null default now(), CHECK (((confidence >= (0)::numeric) AND (confidence <= (1)::numeric))), CHECK ((inference_type = ANY (ARRAY['competitive_intensity'::text, 'market_attractiveness'::text, 'growth_trajectory'::text, 'cyclicality_risk'::text, 'barrier_to_entry'::text, 'regulatory_burden'::text, 'geographic_concentration'::text, 'tailwind'::text, 'headwind'::text, 'other'::text]))), CHECK ((cardinality(input_fact_ids) > 0)), PRIMARY KEY (id));
create table public.buddy_research_missions (id uuid not null default gen_random_uuid(), deal_id uuid not null, bank_id uuid, mission_type text not null, subject jsonb not null default '{}'::jsonb, depth text not null default 'overview'::text, status text not null default 'queued'::text, error_message text, sources_count integer not null default 0, facts_count integer not null default 0, inferences_count integer not null default 0, created_at timestamp with time zone not null default now(), started_at timestamp with time zone, completed_at timestamp with time zone, created_by uuid, correlation_id text, run_key text, max_sources integer, max_fetch_seconds integer, max_extract_seconds integer, timeboxed boolean not null default false, force_rerun boolean not null default false, resume_from_checkpoint uuid, current_stage text, attempt_count integer not null default 1, model_bundle_version text, prompt_bundle_version text, orchestrator_version text, input_fingerprint text, last_heartbeat_at timestamp with time zone, error_count integer not null default 0, warning_count integer not null default 0, summary_json jsonb, cost_usd numeric(10,6), input_tokens integer, output_tokens integer, model_used text, trust_grade text, completion_gate_status text, completion_gate_failures jsonb, entity_confidence numeric, entity_confirmed_name text, entity_lock_json jsonb, threads_succeeded integer default 0, threads_failed integer default 0, threads_null integer default 0, management_profiles_validated boolean, entity_validation_passed boolean, research_quality_computed text, thread_diagnostics jsonb not null default '{}'::jsonb, CHECK ((depth = ANY (ARRAY['overview'::text, 'committee'::text, 'deep_dive'::text]))), CHECK ((mission_type = ANY (ARRAY['industry_landscape'::text, 'competitive_analysis'::text, 'market_demand'::text, 'demographics'::text, 'regulatory_environment'::text, 'management_backgrounds'::text]))), PRIMARY KEY (id), CHECK ((status = ANY (ARRAY['queued'::text, 'running'::text, 'complete'::text, 'failed'::text, 'cancelled'::text]))));
create table public.buddy_research_narratives (id uuid not null default gen_random_uuid(), mission_id uuid not null, sections jsonb not null, version integer not null default 1, compiled_at timestamp with time zone not null default now(), UNIQUE (mission_id), PRIMARY KEY (id));
create table public.buddy_research_quality_gates (id uuid not null default gen_random_uuid(), mission_id uuid not null, deal_id uuid not null, evaluated_at timestamp with time zone not null default now(), trust_grade text not null, gate_passed boolean not null, quality_score integer, entity_lock_check text not null default 'not_run'::text, entity_confidence numeric, thread_coverage_check text not null default 'not_run'::text, threads_succeeded integer, threads_failed integer, source_diversity_check text not null default 'not_run'::text, source_count integer, primary_source_count integer, secondary_source_count integer, management_validation_check text not null default 'not_run'::text, principals_confirmed integer, principals_unconfirmed integer, litigation_source_check text not null default 'not_run'::text, synthesis_check text not null default 'not_run'::text, contradictions_found integer, underwriting_questions_found integer, gate_failures jsonb, thread_results jsonb, section_source_statuses jsonb not null default '[]'::jsonb, contradiction_checklist jsonb not null default '[]'::jsonb, evidence_quality jsonb, preliminary_eligible boolean not null default false, committee_eligible boolean not null default false, preliminary_basis text, committee_blockers jsonb not null default '[]'::jsonb, UNIQUE (mission_id), PRIMARY KEY (id));
create table public.buddy_research_sources (id uuid not null default gen_random_uuid(), mission_id uuid not null, source_class text not null, source_name text not null, source_url text not null, raw_content jsonb, content_type text, checksum text not null, retrieved_at timestamp with time zone not null default now(), http_status integer, fetch_duration_ms integer, fetch_error text, PRIMARY KEY (id), CHECK ((source_class = ANY (ARRAY['government'::text, 'regulatory'::text, 'industry'::text, 'company'::text, 'geography'::text, 'news'::text]))));